import numpy as np
from scipy.optimize import least_squares
def mm_(p):
    return p[0]*np.exp(-p[1]*t**p[2]) - p[3]*A**p[4]*t**p[5]*np.exp(-p[6]*t)
best=None
for s in range(40):
    rng=np.random.default_rng(s)
    p0=np.array([10.1,0.0155,2,0.3,2.5,0.5,0.05])*np.exp(rng.normal(0,0.25,7))
    try:
        r=least_squares(lambda p: mm_(p)-dA_dt, p0, max_nfev=3000)
        v=np.mean(r.fun**2)/np.var(dA_dt)
        if np.isfinite(v) and (best is None or v<best[0]): best=(v,r.x)
    except Exception: pass
print(best[0]); print(np.round(best[1],6))
